<?php if (!empty($user['mfa_secret'])): ?><div class="field"><label for="<?= e($prefix) ?>-code">Current verification or recovery code</label><input id="<?= e($prefix) ?>-code" name="code" autocomplete="one-time-code" required></div><?php elseif (empty($user['password_hash'])): ?><p>Sign in again using your original provider within five minutes before confirming this change.</p><?php else: ?><div class="field"><label for="<?= e($prefix) ?>-password">Current password</label><input id="<?= e($prefix) ?>-password" name="current_password" type="password" autocomplete="current-password" required></div><?php endif; ?>
